{
  const principal = 300000;  // CHF
  const annualRate = 1.8;    // % per year
  const years = 25;
  const r = annualRate / 100 / 12, n = years * 12;
  const payment = r === 0 ? principal / n : principal * r / (1 - Math.pow(1 + r, -n));
  return md`**Monthly payment: CHF ${payment.toFixed(2)}**  
Total paid: CHF ${(payment*n).toFixed(0)} · interest: CHF ${(payment*n - principal).toFixed(0)}  
Formula: P·r / (1 − (1+r)^−n), r = rate/12, n = years·12`;
}

